package com.tapeverify.copilot.controller;
import com.tapeverify.copilot.dto.*; import com.tapeverify.copilot.service.AuditService; import com.tapeverify.copilot.repository.LoanRepository; import com.tapeverify.copilot.util.HashUtil; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/loans") public class AuditController { private final AuditService service; private final LoanRepository loans; public AuditController(AuditService service,LoanRepository loans){this.service=service;this.loans=loans;} @GetMapping("/{id}/audit") List<AuditLogDto> audit(@PathVariable Long id){return service.history(id);}@GetMapping("/{id}/integrity") IntegrityDto integrity(@PathVariable Long id){var loan=loans.findById(id).orElseThrow(()->new IllegalArgumentException("Loan not found"));boolean ok=HashUtil.hash(loan).equals(loan.getSha256Hash());return IntegrityDto.builder().loanId(id).verified(ok).status(ok?"Integrity verified":"Integrity mismatch").build();} }
